shader.userShaderPatched:
// Primitive Intelligence Study ARTEX.glsl
// Audio-reactive iris — loudness expands the core, bass increases ring weight,
// pitch shifts internal hue, and intervals tint the outer shell.
precision mediump float;
uniform float time;
uniform float iTime;
uniform float uTargetAspect;
uniform float targetAspect;
uniform vec3 iResolution;
uniform vec3 iChannelResolution[4];
uniform sampler2D uMainImage;
uniform vec2 uMainImageResolution;
uniform sampler2D uStateA;
uniform vec2 uStateAResolution;
uniform sampler2D uStateB;
uniform vec2 uStateBResolution;
uniform sampler2D uStateC;
uniform vec2 uStateCResolution;
uniform sampler2D uStateD;
uniform vec2 uStateDResolution;
uniform sampler2D uMask;
uniform sampler2D uState1;
uniform sampler2D uState2;
uniform int uUseStateBlending;
uniform float uBlendFactor;
uniform int uStateCount;
uniform int uFlowEnabled;
uniform float uFlowIntensity;
uniform float uFlowSpeed;
uniform float uFlowScale;
uniform vec4 uMediaTransform;
uniform vec4 u_mediaTransform;
uniform int uMediaTransformMainEnabled;
uniform vec4 iDate;
uniform vec4 iMouse;
uniform float uAudioLevel;
uniform float uBassLevel;
uniform float uProximity;
uniform float uCameraLevel;
uniform vec2 uLeftEye;
uniform vec2 uRightEye;
uniform vec2 uFaceCenter;
uniform float uHasFace;
uniform vec2 leftEye;
uniform vec2 rightEye;
uniform vec2 faceCenter;
uniform float hasFace;

uniform float uTime;
uniform vec2 uResolution;
uniform float uEffectStrength;
uniform float uEffectParam1;
uniform float uEffectParam2;
uniform float uEffectParam3;

// ---- Utilities ----

#define PI  3.14159265359
#define TAU 6.28318530718

float hash(float p) {
  return fract(sin(p * 127.1) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i.x + i.y * 57.0);
  float b = hash(i.x + 1.0 + i.y * 57.0);
  float c = hash(i.x + (i.y + 1.0) * 57.0);
  float d = hash(i.x + 1.0 + (i.y + 1.0) * 57.0);
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p, int oct) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 6; i++) {
    if (i >= oct) break;
    v += a * noise(p);
    p *= 2.1;
    a *= 0.48;
  }
  return v;
}

vec3 hueShift(vec3 col, float shift) {
  float angle = shift * TAU;
  float s = sin(angle);
  float c = cos(angle);
  vec3 weights = vec3(0.2126, 0.7152, 0.0722);
  float p = dot(col, weights);
  return vec3(
    p + (col.r - p) * c + (col.r - p) * s * 0.0,
    p + (col.g - p) * c + (col.g - p) * s * -0.5774,
    p + (col.b - p) * c + (col.b - p) * s * 0.5774
  );
}

// ---- Iris pattern ----

float irisPattern(vec2 uv, float r, float t, float audio, float bass) {
  float angle = atan(uv.y, uv.x);
  float dist  = length(uv);

  // Radial fibres
  float fibreCount = 24.0 + bass * 12.0;
  float fibres = sin(angle * fibreCount + t * 0.5) * 0.5 + 0.5;
  fibres = pow(fibres, 2.0 + audio * 3.0);

  // Concentric rings — weight increases with bass
  float ringFreq = 18.0 + bass * 10.0;
  float rings = sin(dist * ringFreq - t * 1.2) * 0.5 + 0.5;
  rings = pow(rings, 1.5);

  // Organic distortion via FBM
  float warp = fbm(uv * 3.0 + t * 0.15, 4) * 0.4;
  float pattern = mix(fibres, rings, 0.5 + warp * 0.3);

  // Iris boundary falloff
  float innerEdge = smoothstep(r * 0.2, r * 0.35, dist);
  float outerEdge = 1.0 - smoothstep(r * 0.75, r, dist);

  return pattern * innerEdge * outerEdge;
}

// ---- Outer shell ----

float shellGlow(vec2 uv, float r, float t, float bass) {
  float dist = length(uv);
  float shellInner = r * 0.95;
  float shellOuter = r * 1.4 + bass * 0.15;

  float glow = smoothstep(shellInner, shellOuter, dist);
  glow *= 1.0 - smoothstep(shellOuter, shellOuter + 0.2, dist);

  // Pulsing ring
  float ringPulse = sin(t * 2.0 + dist * 12.0) * 0.5 + 0.5;
  glow *= 0.6 + 0.4 * ringPulse;

  return glow;
}

// ---- Pupil ----

float pupil(vec2 uv, float radius) {
  float d = length(uv);
  return 1.0 - smoothstep(radius * 0.85, radius, d);
}

// ---- Main ----

void main() {
  float t = uTime > 0.0 ? uTime : iTime > 0.0 ? iTime : time;
  vec2 res = uResolution.x > 0.0 ? uResolution : iResolution.xy;
  vec2 uv = (gl_FragCoord.xy - res * 0.5) / min(res.x, res.y);

  // Audio inputs (smoothed by engine)
  float audio = clamp(uAudioLevel, 0.0, 1.0);
  float bass  = clamp(uBassLevel, 0.0, 1.0);

  // Param controls
  float irisScale   = 0.25 + uEffectParam1 * 0.35;   // overall iris size
  float hueOffset   = uEffectParam2;                   // hue rotation
  float complexity   = 0.5 + uEffectParam3 * 0.5;     // pattern density

  // Core radius expands with loudness
  float baseRadius = irisScale;
  float coreRadius = baseRadius + audio * 0.12;

  // Pupil contracts with loudness (like a real eye)
  float pupilRadius = coreRadius * (0.22 - audio * 0.08);
  float pupilMask = pupil(uv, pupilRadius);

  // Iris body
  float iris = irisPattern(uv, coreRadius, t * complexity, audio, bass);

  // Base warm palette — hue-shifted by pitch (param2) and bass
  vec3 irisColorInner = vec3(0.85, 0.35, 0.12); // amber core
  vec3 irisColorOuter = vec3(0.20, 0.10, 0.06); // dark umber
  irisColorInner = hueShift(irisColorInner, hueOffset + bass * 0.12);
  irisColorOuter = hueShift(irisColorOuter, hueOffset + bass * 0.06);

  float dist = length(uv);
  float radialMix = smoothstep(pupilRadius, coreRadius, dist);
  vec3 irisColor = mix(irisColorInner, irisColorOuter, radialMix);

  // Audio luminance boost
  irisColor += iris * 0.35 * (1.0 + audio * 0.8);

  // Outer shell — tinted by interval (bass-to-treble ratio)
  float shell = shellGlow(uv, coreRadius, t, bass);
  vec3 shellColor = vec3(0.45, 0.18, 0.08);
  shellColor = hueShift(shellColor, hueOffset + 0.15);
  shellColor *= 0.5 + bass * 0.6;

  // Specular highlight on the iris
  vec2 lightDir = vec2(0.3, 0.4);
  float spec = pow(max(dot(normalize(uv), normalize(lightDir)), 0.0), 16.0);
  spec *= smoothstep(coreRadius * 1.1, coreRadius * 0.3, dist);

  // Compose layers
  vec3 bg = vec3(0.02, 0.01, 0.01);
  vec3 col = bg;

  // Shell layer
  col = mix(col, shellColor, shell * 0.7);

  // Iris layer
  float irisMask = smoothstep(coreRadius + 0.01, coreRadius - 0.02, dist)
                 * (1.0 - smoothstep(pupilRadius - 0.01, pupilRadius + 0.02, 0.0));
  col = mix(col, irisColor, irisMask);

  // Pupil (near black with subtle reflection)
  vec3 pupilColor = vec3(0.01, 0.005, 0.005) + spec * 0.3;
  col = mix(col, pupilColor, pupilMask * 0.95);

  // Global specular
  col += spec * vec3(1.0, 0.95, 0.85) * 0.25;

  // Subtle vignette
  float vignette = 1.0 - dot(uv * 0.8, uv * 0.8);
  col *= smoothstep(0.0, 0.6, vignette);

  // Breathing idle pulse when no audio
  float idle = (1.0 - audio) * 0.03 * sin(t * 0.8);
  col += idle;

  // Effect strength mix
  float strength = clamp(uEffectStrength, 0.0, 1.0);
  vec4 media = texture2D(uMainImage, gl_FragCoord.xy / res);
  col = mix(media.rgb, col, strength);

  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
